(function(){
  var n=document.querySelector('nav.glass'),b=n&&n.querySelector('.mb');if(!b)return;
  function set(o){n.classList.toggle('open',o);b.setAttribute('aria-expanded',o?'true':'false')}
  b.addEventListener('click',function(e){e.stopPropagation();set(!n.classList.contains('open'))});
  n.querySelectorAll('a').forEach(function(a){a.addEventListener('click',function(){set(false)})});
  document.addEventListener('click',function(e){if(!n.contains(e.target))set(false)});
  document.addEventListener('keydown',function(e){if(e.key==='Escape')set(false)});
  window.addEventListener('resize',function(){if(window.innerWidth>640)set(false)});
})();
